@Override public boolean isCached(RequestAuthenticator authenticator){
  HttpSession session=getSession(false);
  if (session == null) {
    log.debug("session was null, returning null");
    return false;
  }
  KeycloakUndertowAccount account=(KeycloakUndertowAccount)session.getAttribute(KeycloakUndertowAccount.class.getName());
  if (account == null) {
    log.debug("Account was not in session, returning null");
    return false;
  }
  if (!deployment.getRealm().equals(account.getKeycloakSecurityContext().getRealm())) {
    log.debug("Account in session belongs to a different realm than for this request.");
    return false;
  }
  account.setCurrentRequestInfo(deployment,this);
  try {
    if (account.checkActive()) {
      log.debug("Cached account found");
      securityContext.authenticationComplete(account,"KEYCLOAK",false);
      ((AbstractUndertowRequestAuthenticator)authenticator).propagateKeycloakContext(account);
      restoreRequest();
      return true;
    }
    else {
      log.debug("Refresh failed. Account was not active. Returning null and invalidating Http session");
      session.setAttribute(KeycloakUndertowAccount.class.getName(),null);
      session.invalidate();
      return false;
    }
  } catch (IndexOutOfBoundsException e) {
    log.debug("Index out of bounds while checking account activity");
    session.setAttribute(KeycloakUndertowAccount.class.getName(),null);
    session.invalidate();
    return false;
  } catch (RuntimeException e) {
    log.debug("Runtime exception while checking account activity", e);
    session.setAttribute(KeycloakUndertowAccount.class.getName(),null);
    session.invalidate();
    return false;
  }
}
